  "implementation": "def solve(case):
    segs = case['segments']
    budget = case['budget']
    n = len(segs)
    min_sum = sum(s['minimum'] for s in segs)
    cap_sum = sum(s['capacity'] for s in segs)
    if budget < min_sum or budget > cap_sum:
        raise ValueError('Budget out of feasible range')
    alloc = [s['minimum'] for s in segs]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_priority = -1.0
        for i in range(n):
            if alloc[i] < segs[i]['capacity']:
                priority = segs[i]['importance'] / (alloc[i] + 1)
                if priority > best_priority:
                    best_priority = priority
                    best_idx = i
        if best_idx == -1:
            raise ValueError('Capacity limit reached unexpectedly')
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {segs[i]['name']: alloc[i] for i in range(n)}
    return {'allocations': alloc, 'by_name': by_name, 'total': budget}
